-- ───────────── 20261020_fretes_cubagem_revisao_cg.sql ─────────────
-- Controle de Fretes: cubagem na tabela combinada + revisão das tabelas de Campo Grande.
-- 1) Coluna nova (rodar em CADA projeto: Cuiabá e Campo Grande).
alter table public.frete_tabelas
  add column if not exists cubagem_kg_m3 numeric(8,2);  -- peso cubado = m³ × este fator (ex.: 300 kg/m³)
notify pgrst, 'reload schema';

-- 2) Só Campo Grande (no projeto de Cuiabá não faz nada, porque não há linhas 'CGR' lá):
--    Pantanal: cubagem rodoviária 300 kg/m³.
update public.frete_tabelas set cubagem_kg_m3 = 300 where filial = 'CGR' and transportadora = 'PANTANAL TRANSPORTES';
--    Viatur: pedágio de R$ 5,00 a cada 100 kg nas cidades sublinhadas na proposta.
--    LH: R$ 0,60/kg acima de 50 kg (cubagem) no interior.
delete from public.frete_tabelas where filial = 'CGR' and transportadora in ('VIATUR', 'LH TRANSPORTES');
