select 'LOGMED', v.rota, v.peso_ate::numeric, null, v.fixo::numeric, v.kg::numeric, v.pct::numeric, null, 'total', 300,
       5.70, 100, null, null, null, 'somar', null, null, v.obs, v.origens, v.destinos, f.filial
